import { createHash, randomBytes } from 'node:crypto';
import { domainToASCII } from 'node:url';
import fs from 'node:fs/promises';
import path from 'node:path';

const TYPES = new Set(['unsubscribe', 'spam_complaint', 'hard_bounce']);
const KINDS = new Set(['marketing', 'transactional']);

// Which event types block which kind of mail, in the order they are reported.
const BLOCKS = [
  { type: 'hard_bounce', rule: 'hard-bounce', kinds: ['marketing', 'transactional'] },
  { type: 'spam_complaint', rule: 'spam-complaint', kinds: ['marketing'] },
  { type: 'unsubscribe', rule: 'unsubscribed', kinds: ['marketing'] },
];

// Reduce the many ways one mailbox can be written to a single canonical key.
// Returns null when the input is not a usable address.
export function normalizeEmail(input) {
  if (typeof input !== 'string') return null;
  let s = input.normalize('NFKC').replace(/[​-‍⁠﻿]/g, '').trim();
  // "Display Name <<EMAIL>>"
  const angle = s.match(/<([^<>]*)>\s*$/);
  if (angle) s = angle[1].trim();
  s = s.replace(/^mailto:/i, '').trim();
  const at = s.lastIndexOf('@');
  if (at < 1) return null;
  let local = s.slice(0, at).trim();
  let domain = s.slice(at + 1).trim();
  if (local.length > 1 && local.startsWith('"') && local.endsWith('"')) local = local.slice(1, -1);
  local = local.toLowerCase();
  domain = domain.replace(/\.+$/, '').toLowerCase();
  domain = domainToASCII(domain);
  if (!local || !domain || /\s/.test(local) || local.includes('@')) return null;
  if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(domain)) return null;
  if (domain === 'googlemail.com') domain = 'gmail.com';
  // Plus tags deliver to the same mailbox: suppress the mailbox, not the tag.
  const plus = local.indexOf('+');
  if (plus >= 0) local = local.slice(0, plus);
  if (domain === 'gmail.com') local = local.replace(/\./g, '');
  if (!local) return null;
  return `${local}@${domain}`;
}

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error('STATE_DIR is not set');
  return path.resolve(dir);
}

function fileFor(dir, key, type) {
  const h = createHash('sha256').update(key).digest('hex');
  return path.join(dir, `${h}.${type}`);
}

async function fsyncDir(dir) {
  let fh;
  try {
    fh = await fs.open(dir, 'r');
    await fh.sync();
  } catch {
    // Not supported on every platform; the file itself was already synced.
  } finally {
    await fh?.close();
  }
}

async function exists(file) {
  try {
    await fs.access(file);
    return true;
  } catch (e) {
    if (e.code === 'ENOENT') return false;
    throw e;
  }
}

export async function recordEvent({ email, type, now } = {}) {
  if (!TYPES.has(type)) throw new TypeError(`unknown event type: ${String(type)}`);
  const key = normalizeEmail(email);
  if (!key) throw new TypeError(`invalid email address: ${String(email)}`);
  const dir = stateDir();
  await fs.mkdir(dir, { recursive: true });
  const final = fileFor(dir, key, type);
  const at = now instanceof Date && !Number.isNaN(now.getTime()) ? now.toISOString() : null;
  const tmp = path.join(dir, `.tmp-${process.pid}-${randomBytes(8).toString('hex')}`);
  try {
    // Write the whole file privately, then publish it atomically. link() fails
    // if the event is already recorded, so the first record wins and readers
    // never see a partial file. No locks are needed.
    const fh = await fs.open(tmp, 'wx');
    try {
      await fh.writeFile(JSON.stringify({ email: key, type, at }) + '\n');
      await fh.sync();
    } finally {
      await fh.close();
    }
    try {
      await fs.link(tmp, final);
    } catch (e) {
      if (e.code !== 'EEXIST') throw e;
    }
    await fsyncDir(dir);
  } finally {
    await fs.rm(tmp, { force: true });
  }
}

export async function checkEmail({ email, kind, now } = {}) {
  if (!KINDS.has(kind)) return { allowed: false, rule: 'invalid-kind' };
  const key = normalizeEmail(email);
  if (!key) return { allowed: false, rule: 'invalid-address' };
  const dir = stateDir();
  for (const b of BLOCKS) {
    if (b.kinds.includes(kind) && (await exists(fileFor(dir, key, b.type)))) {
      return { allowed: false, rule: b.rule };
    }
  }
  return { allowed: true, rule: '' };
}

import { spawnSync, spawn } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';

const BOT = process.argv[2];
const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'botstate-'));
process.env.STATE_DIR = path.join(dir, 'nested');
const { recordEvent, checkEmail } = await import(BOT);
const now = new Date();

const c = (email, kind) => checkEmail({ email, kind, now });
assert.deepEqual(await c('<EMAIL>', 'marketing'), { allowed: true, rule: '' });
await recordEvent({ email: ' Jane Doe <Jane.Doe+news@Example.COM> ', type: 'unsubscribe', now });
const u = await c('JANE.DOE@example.com.', 'marketing');
assert.equal(u.allowed, false);
assert.equal((await c('jane.doe@example.com', 'transactional')).allowed, true);
await recordEvent({ email: '<EMAIL>', type: 'spam_complaint', now });
const s = await c('<EMAIL>', 'marketing');
assert.equal(s.allowed, false); assert.notEqual(s.rule, u.rule);
await recordEvent({ email: '<EMAIL>', type: 'hard_bounce', now });
const h = await c('<EMAIL>', 'transactional');
assert.equal(h.allowed, false); assert.notEqual(h.rule, s.rule); assert.notEqual(h.rule, u.rule);
await recordEvent({ email: '<EMAIL>', type: 'unsubscribe', now });
assert.equal((await c('<EMAIL>', 'marketing')).allowed, false);
assert.equal((await c('nope', 'marketing')).allowed, false);
assert.equal((await c('<EMAIL>', 'other')).allowed, false);

// concurrent writers in separate processes, then a fresh process reads back
const child = `import {recordEvent} from ${JSON.stringify(BOT)};
const n=+process.argv[2];const jobs=[];
for(let i=0;i<50;i++){jobs.push(recordEvent({email:'u'+i+'@x.com',type:'unsubscribe',now:new Date()}));
jobs.push(recordEvent({email:'<EMAIL>',type:'hard_bounce',now:new Date()}));}
await Promise.all(jobs);`;
fs.writeFileSync('/tmp/botcheck/child.mjs', child);
await Promise.all([...Array(6)].map(() => new Promise((res, rej) => {
  const p = spawn('node', ['/tmp/botcheck/child.mjs'], { env: process.env, stdio: 'inherit' });
  p.on('exit', (code) => (code === 0 ? res() : rej(new Error('child failed'))));
})));
const r = spawnSync('node', ['-e', `
import(${JSON.stringify(BOT)}).then(async m=>{
 for(let i=0;i<50;i++){const r=await m.checkEmail({email:'u'+i+'@x.com',kind:'marketing',now:new Date()});if(r.allowed)throw new Error('missing u'+i)}
 const r=await m.checkEmail({email:'<EMAIL>',kind:'transactional',now:new Date()});if(r.allowed)throw new Error('same');
 console.log('fresh process ok')})`], { env: process.env, encoding: 'utf8' });
console.log(r.stdout, r.stderr);
assert.equal(r.status, 0);
const leftovers = fs.readdirSync(process.env.STATE_DIR).filter((f) => f.startsWith('.tmp'));
assert.equal(leftovers.length, 0);
console.log('ALL OK');
